"""Publish a human-readable reference from validated shipped zone definitions."""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))
from warcraft_survivors.content import load_content  # noqa: E402


def main():
    c = load_content()
    lines = [
        "# Zone and boss catalog — v0.5.0",
        "",
        "Generated by `scripts/zone_catalog.py`; all maps are finite 8192×8192. All five are available to new and migrated profiles. A zone's threat rating describes relative tuning, rather than a universal stat multiplier. Boss pools are independent extensible lists; the release includes one final boss per zone.",
        "",
    ]
    for z in c.zones.values():
        lines += [
            "## " + z.name,
            "",
            z.description,
            "",
            f"Seed {z.seed}; rating {z.difficulty:g}; terrain `{z.ground}` / `{z.road}`; music `{z.music}`.",
            "",
            "Landmarks: " + ", ".join(p.name for p in z.landmarks) + ".",
            "",
            "| Enemy | Base HP | Speed | Damage | Run XP | Class XP | Behavior | Earliest second |",
            "|---|---:|---:|---:|---:|---:|---|---:|",
        ]
        for eid in z.enemies:
            e = c.enemies[eid]
            lines.append(
                f"| {e.name} | {e.health:g} | {e.speed:g} | {e.damage:g} | {e.xp:g} | {e.class_xp} | {e.behavior} | {e.min_time:g} |"
            )
        lines += [
            "",
            "Elite pool: "
            + ", ".join(c.elites[e].name for e in z.elites)
            + ". Spawn at 5/10/15/20/25 minutes; survivors remain, and kills drop evolution-eligible chests.",
            "",
        ]
        for bid in z.boss_pool:
            b = c.bosses[bid]
            lines += [
                f"### {b.name}",
                "",
                f"Base HP {b.health:g}, contact damage {b.damage:g}, speed {b.speed:g}, body radius {b.radius:g}. HP multiplier `1 + .008 × max(0, player level−30)`. Enrage at {b.enrage:.0%} HP; cooldown ×{b.enrage_cooldown:g}, damage ×{b.enrage_damage:g}. Kill rewards: {b.xp:g} run XP, {b.class_xp} class XP, {b.gold} banked gold, plus full-run bonuses.",
                "",
                "| Attack | Shape | Base damage | Warning | Duration | Radius | Cooldown | Additional behavior |",
                "|---|---|---:|---:|---:|---:|---:|---|",
            ]
            for aid in b.attacks:
                a = c.attacks[aid]
                extras = []
                if a.pulse:
                    extras.append(f"pulse {a.pulse:g}s")
                if a.growth:
                    extras.append(f"grows {a.growth:g}/s")
                if a.pull:
                    extras.append(f"pull {a.pull:g}")
                if a.slow:
                    extras.append(f"slow {a.slow:.0%} / {a.slow_duration:g}s")
                extras.append(
                    f"{a.count} projectile(s)" if a.kind == "missile" else "locked warning"
                )
                lines.append(
                    f"| {a.name} | {a.kind} | {a.damage:g} | {a.warning:g}s | {a.duration:g}s | {a.radius:g} | {a.cooldown:g}s | {', '.join(extras)} |"
                )
        lines += [
            "",
            "| Minute | Rate / s | Batch | Living density | HP multiplier | Damage multiplier | XP multiplier | Surge |",
            "|---:|---:|---:|---:|---:|---:|---:|---:|",
        ]
        for w in z.waves:
            lines.append(
                f"| {int(w.start) // 60 + 1} | {w.rate:.2f} | {w.batch} | {w.density} | {w.health:.3f} | {w.damage:.3f} | {w.xp:.3f} | {w.surge} |"
            )
        lines += [""]
    lines += [
        "Boss warnings remain visible at every cosmetic quality/density. All boss attack entries add 6% max health before armor, penetrate 0.5 armor, and wound automatic life steal for two seconds on actual health damage. Shields and manual immunity still work. Repeated ground hazards use their pulse interval together with normal hit immunity; staying in Defile lets its radius grow. Victory requires the boss dead and hero alive; 30:00 alone never ends a run.",
        "",
    ]
    (ROOT / "docs/ZONE_CATALOG.md").write_text("\n".join(lines), encoding="utf-8")


if __name__ == "__main__":
    main()
